    #[test]
    fn matrix_single_message_pending_does_not_downgrade_thinking_round() {
        use clawcrew_runtime::agent::loop_::thinking_status_text;

        let mut pending = Vec::new();
        push_matrix_single_message_pending(
            &mut pending,
            DraftProgress::status(thinking_status_text(1)),
            3,
        );
        push_matrix_single_message_pending(
            &mut pending,
            DraftProgress::status(thinking_status_text(0)),
            3,
        );

        assert_eq!(
            pending,
            vec![DraftProgress::status(thinking_status_text(1))]
        );

        push_matrix_single_message_pending(&mut pending, DraftProgress::status("tool\n"), 3);

        push_matrix_single_message_pending(
            &mut pending,
            DraftProgress::status(thinking_status_text(2)),
            3,
        );

        assert_eq!(
            pending,
            vec![
                DraftProgress::status(thinking_status_text(1)),
                DraftProgress::status("tool\n"),
                DraftProgress::status(thinking_status_text(2))
            ]
        );
    }

    #[test]
    fn matrix_single_message_pending_preserves_reasoning_matching_thinking_status() {
        use clawcrew_runtime::agent::loop_::{StreamDelta, thinking_status_text};

        let config = Config::default();
        let status = matrix_progress_text(
            &StreamDelta::Status(thinking_status_text(0)),
            &config,
            "missing",
        )
        .expect("thinking status renders");
        let reasoning = matrix_progress_text(
            &StreamDelta::Reasoning("Thinking...\n".to_string()),
            &config,
            "missing",
        )
        .expect("reasoning renders");
        let mut pending = Vec::new();

        // Equal display text must remain two source-distinct progress entries.
        push_matrix_single_message_pending(&mut pending, status.clone(), 3);
        push_matrix_single_message_pending(&mut pending, reasoning.clone(), 3);

        assert_eq!(
            status.text, reasoning.text,
            "the regression requires an exact display-text collision"
        );
        assert_ne!(status.kind, reasoning.kind);
        assert_eq!(pending, vec![status, reasoning]);
    }

    struct SlowBatchChannel {
        batches: Arc<tokio::sync::Mutex<Vec<Vec<String>>>>,
        delay: Duration,
    }

    impl ::clawcrew_api::attribution::Attributable for SlowBatchChannel {
        fn role(&self) -> ::clawcrew_api::attribution::Role {
            ::clawcrew_api::attribution::Role::Channel(
                ::clawcrew_api::attribution::ChannelKind::Matrix,
            )
        }

        fn alias(&self) -> &str {
            "slow-batch"
        }
    }

    #[async_trait::async_trait]
    impl Channel for SlowBatchChannel {
        fn name(&self) -> &str {
            "slow-batch"
        }

        async fn send(&self, _message: &SendMessage) -> anyhow::Result<()> {
            Ok(())
        }

        async fn listen(
            &self,
            _tx: tokio::sync::mpsc::Sender<clawcrew_api::channel::ChannelMessage>,
        ) -> anyhow::Result<()> {
            Ok(())
        }

        async fn update_draft_progress_batch(
            &self,
            _recipient: &str,
            _message_id: &str,
            texts: &[String],
        ) -> anyhow::Result<()> {
            tokio::time::sleep(self.delay).await;
            self.batches.lock().await.push(texts.to_vec());
            Ok(())
        }
    }

    #[tokio::test]
    async fn matrix_single_message_progress_coalesces_slow_flush() {
        use clawcrew_runtime::agent::loop_::{REASONING_FULL_PREFIX, StreamDelta};

        let batches = Arc::new(tokio::sync::Mutex::new(Vec::<Vec<String>>::new()));
        let channel: Arc<dyn Channel> = Arc::new(SlowBatchChannel {
            batches: Arc::clone(&batches),
            delay: Duration::from_millis(150),
        });
        let (tx, rx) = tokio::sync::mpsc::channel(64);
        let updater = clawcrew_spawn::spawn!(run_matrix_single_message_draft_updater(
            rx,
            channel,
            "room".to_string(),
            "draft".to_string(),
            50,
            5,
            Arc::new(Config::default()),
            "test".to_string(),
        ));

        for idx in 0..20 {
            tx.send(StreamDelta::Reasoning(format!(" pre{idx}")))
                .await
                .unwrap();
        }
        tokio::time::sleep(Duration::from_millis(80)).await;

        for idx in 0..80 {
            tx.send(StreamDelta::Text(format!("answer-{idx}")))
                .await
                .unwrap();
            tx.send(StreamDelta::Reasoning(format!(" post{idx}")))
                .await
                .unwrap();
            tx.send(StreamDelta::Status(format!("tool-{idx}\n")))
                .await
                .unwrap();
        }
        drop(tx);

        tokio::time::timeout(Duration::from_secs(3), updater)
            .await
            .expect("single-message updater should finish")
            .expect("single-message updater task should not panic");

        let batches = batches.lock().await.clone();
        assert!(
            (2..=4).contains(&batches.len()),
            "slow flush should coalesce many deltas into a few batch edits, got {batches:?}"
        );
        assert!(
            batches.iter().all(|batch| batch.len() <= 5),
            "batch staging should be bounded by stream_draft_lines, got {batches:?}"
        );
        assert!(
            batches
                .iter()
                .flatten()
                .filter(|line| line.starts_with(REASONING_FULL_PREFIX))
                .count()
                > batches.len(),
            "interleaved tool progress should keep reasoning split into multiple entries, got {batches:?}"
        );
        assert!(
            batches
                .iter()
                .flatten()
                .any(|line| line.starts_with("tool-")),
            "latest tool progress should remain available as a boundary line, got {batches:?}"
        );
        assert!(
            !batches
                .iter()
                .flatten()
                .any(|line| line.starts_with("answer-")),
            "single-message progress updater must ignore assistant Text deltas: {batches:?}"
        );
    }

    #[test]
    fn channel_doctor_surfaces_dangling_peer_group_channel_warning() {
        // The dangling `peer_groups.<name>.channel` diagnostic belongs on the
        // `clawcrew channel doctor` path, not only the general doctor.
        // `doctor_channels()` reaches the user through
        // `peer_group_dangling_warning_lines`, which is derived from the shared
        // `Config::collect_warnings()` source of truth (no second validator).
        use clawcrew_config::multi_agent::PeerGroupConfig;

        let mut config = Config::default();
        // A dangling reference: `telegram.typo` names no configured
        // `[channels.telegram.typo]` block.
        config.peer_groups.insert(
            "ops".to_string(),
            PeerGroupConfig {
                channel: "telegram.typo".into(),
                ..Default::default()
            },
        );

        let lines = super::peer_group_dangling_warning_lines(&config);
        assert_eq!(
            lines.len(),
            1,
            "exactly one dangling peer-group warning expected: {lines:?}"
        );
        assert!(
            lines[0].contains("peer group") && lines[0].contains("peer_groups.ops.channel"),
            "warning line must name the offending peer group and path: {}",
            lines[0]
        );
        assert!(
            lines[0].contains("telegram.typo"),
            "warning line must echo the dangling reference: {}",
            lines[0]
        );
    }

    #[test]
    fn channel_doctor_silent_when_no_dangling_peer_group_ref() {
        // Control: a peer group whose channel resolves to a configured block
        // must not produce a dangling warning on the channel-doctor path.
        use clawcrew_config::multi_agent::PeerGroupConfig;

        let mut config = Config::default();
        config.channels.telegram.insert(
            "work".to_string(),
            clawcrew_config::schema::TelegramConfig::default(),
        );
        config.peer_groups.insert(
            "ops".to_string(),
            PeerGroupConfig {
                channel: "telegram.work".into(),
                ..Default::default()
            },
        );

        let lines = super::peer_group_dangling_warning_lines(&config);
        assert!(
            lines.is_empty(),
            "no dangling warning expected for a resolvable ref: {lines:?}"
        );
    }

    #[tokio::test]
    async fn channel_runtime_reload_applies_env_overrides_after_migration() {
        let tmp = TempDir::new().unwrap();
        let config_path = tmp.path().join("config.toml");
        std::fs::write(
            &config_path,
            r#"
default_provider = "openrouter"

[model_providers.openrouter]
name = "openrouter"

[agents.demo]
provider = "openrouter"
model = "meta-llama/llama-3.1-8b-instruct"
temperature = 0.3
"#,
        )
        .unwrap();

        let env_name = "CLAWCREW_providers__models__openrouter__agent_demo__api_key";
        // SAFETY: this test owns this specific env-var key and restores it
        // before returning. The value is synthetic and not a real credential.
        unsafe { std::env::set_var(env_name, "sk-or-v1-test-channel-reload") };

        let result = load_runtime_config_and_defaults(&config_path, "demo").await;

        // SAFETY: undo the test-only process env mutation above.
        unsafe { std::env::remove_var(env_name) };

        let (config, defaults) = result.unwrap();
        assert_eq!(
            defaults.api_key.as_deref(),
            Some("sk-or-v1-test-channel-reload")
        );
        assert!(
            config
                .env_overridden_paths
                .contains("providers.models.openrouter.agent_demo.api_key")
        );
    }

