    #[async_trait::async_trait]
    impl Channel for SlowBusyChannel {
        fn name(&self) -> &str {
            "telegram"
        }

        async fn send(&self, message: &SendMessage) -> anyhow::Result<()> {
            let busy = clawcrew_runtime::i18n::get_required_cli_string(
                "channel-runtime-conversation-busy",
            );
            let stop_sent =
                clawcrew_runtime::i18n::get_required_cli_string("channel-runtime-stop-sent");
            let stop_no_task =
                clawcrew_runtime::i18n::get_required_cli_string("channel-runtime-stop-no-task");
            if message.content == busy
                || message.content == stop_sent
                || message.content == stop_no_task
            {
                let current = self.busy_in_flight.fetch_add(1, Ordering::AcqRel) + 1;
                self.max_busy_in_flight.fetch_max(current, Ordering::AcqRel);
                tokio::time::sleep(Duration::from_millis(500)).await;
                self.busy_in_flight.fetch_sub(1, Ordering::AcqRel);
            }
            self.sent_messages
                .lock()
                .await
                .push(format!("{}:{}", message.recipient, message.content));
            Ok(())
        }

        async fn listen(
            &self,
            _tx: tokio::sync::mpsc::Sender<clawcrew_api::channel::ChannelMessage>,
        ) -> anyhow::Result<()> {
            Ok(())
        }

        async fn start_typing(&self, _recipient: &str) -> anyhow::Result<()> {
            Ok(())
        }

        async fn stop_typing(&self, _recipient: &str) -> anyhow::Result<()> {
            Ok(())
        }
    }

