    #[async_trait::async_trait]
    impl Channel for DraftRecordingChannel {
        fn name(&self) -> &str {
            self.channel_name
        }

        async fn send(&self, message: &SendMessage) -> anyhow::Result<()> {
            if self.fallback_send_should_fail {
                anyhow::bail!("fallback send boom")
            }
            self.sent_messages
                .lock()
                .await
                .push(format!("{}:{}", message.recipient, message.content));
            Ok(())
        }

        async fn send_final(&self, message: &SendMessage) -> anyhow::Result<()> {
            self.final_send_calls.fetch_add(1, Ordering::SeqCst);
            self.send(message).await
        }

        async fn listen(
            &self,
            _tx: tokio::sync::mpsc::Sender<clawcrew_api::channel::ChannelMessage>,
        ) -> anyhow::Result<()> {
            Ok(())
        }

        fn supports_draft_updates(&self) -> bool {
            true
        }

        fn supports_multi_message_streaming(&self) -> bool {
            self.supports_multi_message_streaming
        }

        async fn update_draft(
            &self,
            _recipient: &str,
            _message_id: &str,
            text: &str,
        ) -> anyhow::Result<()> {
            self.draft_updates.lock().await.push(text.to_string());
            Ok(())
        }

        async fn send_draft(&self, message: &SendMessage) -> anyhow::Result<Option<String>> {
            self.delivery_events.lock().await.push("draft");
            self.draft_messages
                .lock()
                .await
                .push(format!("{}:{}", message.recipient, message.content));
            Ok(Some("draft-1".to_string()))
        }

        async fn start_typing(&self, _recipient: &str) -> anyhow::Result<()> {
            self.delivery_events.lock().await.push("typing-start");
            if self.stall_start_typing {
                std::future::pending::<()>().await;
            }
            Ok(())
        }

        async fn stop_typing(&self, _recipient: &str) -> anyhow::Result<()> {
            self.delivery_events.lock().await.push("typing-stop");
            if self.stall_stop_typing {
                std::future::pending::<()>().await;
            }
            Ok(())
        }

        async fn finalize_draft(
            &self,
            recipient: &str,
            message_id: &str,
            text: &str,
            _suppress_voice: bool,
        ) -> anyhow::Result<()> {
            if self.finalize_should_fail {
                anyhow::bail!("finalize boom")
            }
            self.finalized_messages
                .lock()
                .await
                .push(format!("{recipient}:{message_id}:{text}"));
            Ok(())
        }

        async fn cancel_draft(&self, recipient: &str, message_id: &str) -> anyhow::Result<()> {
            self.cancelled_drafts
                .lock()
                .await
                .push(format!("{recipient}:{message_id}"));
            Ok(())
        }

        fn supports_turn_flush_narration(&self) -> bool {
            self.turn_flush_capable
        }

        async fn flush_draft_turn(
            &self,
            _recipient: &str,
            _message_id: &str,
            text: &str,
        ) -> anyhow::Result<()> {
            self.flushed_turns.lock().await.push(text.to_string());
            Ok(())
        }

        async fn discard_draft_turn(
            &self,
            _recipient: &str,
            _message_id: &str,
            text: &str,
        ) -> anyhow::Result<()> {
            self.discarded_turns.lock().await.push(text.to_string());
            Ok(())
        }

        async fn update_draft_progress(
            &self,
            _recipient: &str,
            _message_id: &str,
            text: &str,
        ) -> anyhow::Result<()> {
            self.progress_messages.lock().await.push(text.to_string());
            Ok(())
        }

        async fn update_draft_lifecycle(
            &self,
            _recipient: &str,
            _message_id: &str,
            event: clawcrew_runtime::agent::loop_::ProgressEvent,
        ) -> anyhow::Result<()> {
            self.lifecycle_events.lock().await.push(event);
            Ok(())
        }
    }

