    #[tokio::test]
    async fn passive_context_records_history_without_channel_or_model_side_effects() {
        let channel_impl = Arc::new(RecordingChannel::default());
        let channel: Arc<dyn Channel> = channel_impl.clone();
        let provider_impl = Arc::new(HistoryCaptureModelProvider::default());
        let provider: Arc<dyn ModelProvider> = provider_impl.clone();
        let runtime_ctx = test_runtime_ctx_with_config_agent_and_provider_ref(
            channel,
            provider,
            clawcrew_config::schema::Config::default(),
            clawcrew_config::schema::AliasedAgentConfig::default(),
            "test-provider",
            None,
        );

        let passive_msg = clawcrew_api::channel::ChannelMessage {
            id: "passive-1".into(),
            sender: "bob".into(),
            reply_target: "group-1@g.us".into(),
            content: "the release codename is quartz".into(),
            channel: "whatsapp".into(),
            timestamp: 1,
            passive_context: true,
            conversation_scope: clawcrew_api::channel::ChannelConversationScope::ReplyTarget,
            ..Default::default()
        };

        process_channel_message(
            runtime_ctx.clone(),
            passive_msg.clone(),
            CancellationToken::new(),
        )
        .await;

        assert!(
            provider_impl
                .calls
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .is_empty(),
            "passive context must not call the provider"
        );
        assert!(channel_impl.sent_messages.lock().await.is_empty());
        assert!(channel_impl.reactions_added.lock().await.is_empty());
        assert!(channel_impl.reactions_removed.lock().await.is_empty());
        assert_eq!(channel_impl.start_typing_calls.load(Ordering::SeqCst), 0);
        assert_eq!(channel_impl.stop_typing_calls.load(Ordering::SeqCst), 0);

        let active_msg = clawcrew_api::channel::ChannelMessage {
            id: "active-1".into(),
            sender: "alice".into(),
            content: "what is the release codename?".into(),
            timestamp: 2,
            passive_context: false,
            conversation_scope: clawcrew_api::channel::ChannelConversationScope::ReplyTarget,
            ..passive_msg.clone()
        };
        assert_eq!(
            conversation_history_key(&active_msg),
            conversation_history_key(&passive_msg)
        );

        process_channel_message(runtime_ctx, active_msg, CancellationToken::new()).await;

        let calls = provider_impl
            .calls
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        assert_eq!(calls.len(), 1);
        let user_history = calls[0]
            .iter()
            .filter(|(role, _)| role == "user")
            .map(|(_, content)| content.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            user_history.contains("the release codename is quartz"),
            "active turn should see passive group context, got: {user_history}"
        );
        assert!(
            user_history.contains("[Observed WhatsApp group message from bob]"),
            "passive group context should preserve observed sender attribution, got: {user_history}"
        );
        assert!(
            user_history.contains("what is the release codename?"),
            "active turn should still include current message, got: {user_history}"
        );
        assert!(
            user_history.contains("[Current WhatsApp group message from alice]"),
            "active group turn should preserve current sender attribution, got: {user_history}"
        );
    }

    #[tokio::test]
    async fn passive_context_does_not_reach_the_worker_sop_dispatch() {
        use clawcrew_runtime::sop::types::{
            Sop, SopAdmissionPolicy, SopExecutionMode, SopPriority, SopStep, SopTrigger,
        };

        let sop = Sop {
            name: "telegram-ingress".into(),
            description: "Starts on any telegram channel message".into(),
            version: "1.0.0".into(),
            priority: SopPriority::Normal,
            execution_mode: SopExecutionMode::Auto,
            triggers: vec![SopTrigger::Channel {
                channel: "telegram".into(),
                alias: None,
                condition: None,
            }],
            steps: vec![SopStep {
                number: 1,
                title: "Step one".into(),
                body: "Do step one".into(),
                ..Default::default()
            }],
            cooldown_secs: 0,
            max_concurrent: 2,
            location: None,
            deterministic: false,
            admission_policy: SopAdmissionPolicy::Parallel,
            max_pending_approvals: 0,
            agent: None,
        };
        let mut engine =
            clawcrew_runtime::sop::SopEngine::new(clawcrew_config::schema::SopConfig::default());
        engine.set_sops_for_test(vec![sop]);
        let engine = Arc::new(std::sync::Mutex::new(engine));

        let channel: Arc<dyn Channel> = Arc::new(RecordingChannel::default());
        let provider: Arc<dyn ModelProvider> = Arc::new(HistoryCaptureModelProvider::default());
        let base = test_runtime_ctx_with_config_agent_and_provider_ref(
            channel,
            provider,
            clawcrew_config::schema::Config::default(),
            clawcrew_config::schema::AliasedAgentConfig::default(),
            "test-provider",
            None,
        );
        let runtime_ctx = Arc::new(ChannelRuntimeContext {
            sop_engine: Some(Arc::clone(&engine)),
            sop_audit: Some(Arc::new(clawcrew_runtime::sop::SopAuditLogger::new(
                Arc::new(NoopMemory),
            ))),
            ..(*base).clone()
        });

        let passive_msg = clawcrew_api::channel::ChannelMessage {
            id: "passive-1".into(),
            sender: "bob".into(),
            reply_target: "-1001234567890".into(),
            content: "the release codename is quartz".into(),
            channel: "telegram".into(),
            timestamp: 1,
            passive_context: true,
            conversation_scope: clawcrew_api::channel::ChannelConversationScope::ReplyTarget,
            ..Default::default()
        };
        process_channel_message(
            runtime_ctx.clone(),
            passive_msg.clone(),
            CancellationToken::new(),
        )
        .await;

        assert!(
            engine
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .active_runs()
                .is_empty(),
            "passive observation must not start an SOP run"
        );

        let active_msg = clawcrew_api::channel::ChannelMessage {
            id: "active-1".into(),
            sender: "alice".into(),
            content: "what is the release codename?".into(),
            timestamp: 2,
            passive_context: false,
            ..passive_msg
        };
        process_channel_message(runtime_ctx, active_msg, CancellationToken::new()).await;

        assert_eq!(
            engine
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .active_runs()
                .len(),
            1,
            "the addressed turn must still dispatch"
        );
    }

