    #[tokio::test]
    async fn approval_typing_channel_forwards_turn_flush_surface() {
        // The typing wrapper the production approval path installs must not hide
        // the turn-flush capability of the channel it wraps. If it inherited the
        // trait defaults (capability false, no-op flush), `gate_tool_approval`
        // would skip the FlushBarrier and an approval prompt could reach the
        // channel before the permanent pre-tool narration this feature sends first.
        let inner = Arc::new(DraftRecordingChannel {
            turn_flush_capable: true,
            ..DraftRecordingChannel::new(false, false)
        });
        let channel: Arc<dyn Channel> = inner.clone();
        let typing = Arc::new(ScopedTypingController::new(
            Arc::clone(&channel),
            "chat".to_string(),
        ));
        let wrapped = ApprovalTypingChannel::new(Arc::clone(&channel), typing);

        assert!(
            wrapped.supports_turn_flush_narration(),
            "wrapper must forward the wrapped channel's turn-flush capability"
        );
        wrapped
            .flush_draft_turn("chat", "mid", "narration")
            .await
            .unwrap();
        wrapped
            .discard_draft_turn("chat", "mid", "cancelled")
            .await
            .unwrap();
        assert_eq!(
            inner.flushed_turns.lock().await.clone(),
            vec!["narration".to_string()],
            "flush_draft_turn must reach the wrapped channel"
        );
        assert_eq!(
            inner.discarded_turns.lock().await.clone(),
            vec!["cancelled".to_string()],
            "discard_draft_turn must reach the wrapped channel"
        );
    }

    #[tokio::test]
    async fn approval_wait_pauses_typing_and_only_approval_resumes_it() {
        use clawcrew_api::channel::{
            ApprovalSource, AttributedApprovalResponse, ChannelApprovalRequest,
            ChannelApprovalResponse,
        };

        let cases = [
            (
                PendingApprovalOutcome::Response(Some(AttributedApprovalResponse::operator(
                    ChannelApprovalResponse::Approve,
                ))),
                true,
                false,
            ),
            (
                PendingApprovalOutcome::Response(Some(AttributedApprovalResponse::operator(
                    ChannelApprovalResponse::AlwaysApprove,
                ))),
                true,
                false,
            ),
            (
                PendingApprovalOutcome::Response(Some(AttributedApprovalResponse::operator(
                    ChannelApprovalResponse::Deny,
                ))),
                false,
                false,
            ),
            (
                PendingApprovalOutcome::Response(Some(AttributedApprovalResponse::from_runtime(
                    ChannelApprovalResponse::Deny,
                    ApprovalSource::TimedOut,
                ))),
                false,
                false,
            ),
            (PendingApprovalOutcome::Response(None), false, false),
            (PendingApprovalOutcome::Error, false, true),
        ];

        for (outcome, should_resume, should_error) in cases {
            let channel_impl = Arc::new(PendingApprovalChannel::new(outcome));
            let channel: Arc<dyn Channel> = channel_impl.clone();
            let typing = Arc::new(ScopedTypingController::new(
                Arc::clone(&channel),
                "approval-chat".to_string(),
            ));
            typing.resume().await;

            tokio::time::timeout(Duration::from_secs(1), async {
                while channel_impl.start_typing_calls.load(Ordering::SeqCst) < 1 {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("initial typing should start");

            let wrapped = Arc::new(ApprovalTypingChannel::new(
                Arc::clone(&channel),
                Arc::clone(&typing),
            ));
            let approval_task = clawcrew_spawn::spawn!(async move {
                wrapped
                    .request_approval_attributed(
                        "approval-chat",
                        &ChannelApprovalRequest {
                            tool_name: "shell".to_string(),
                            arguments_summary: "command".to_string(),
                            raw_arguments: None,
                            position: None,
                        },
                    )
                    .await
            });

            tokio::time::timeout(
                Duration::from_secs(1),
                channel_impl.approval_started.notified(),
            )
            .await
            .expect("approval request should start");
            assert_eq!(
                channel_impl.stop_typing_calls.load(Ordering::SeqCst),
                1,
                "typing must stop before the approval wait begins"
            );
            assert_eq!(
                channel_impl.start_typing_calls.load(Ordering::SeqCst),
                1,
                "typing must remain paused while approval is pending"
            );

            channel_impl.approval_release.notify_one();
            let approval_result = approval_task.await.unwrap();
            assert_eq!(approval_result.is_err(), should_error);

            if should_resume {
                tokio::time::timeout(Duration::from_secs(1), async {
                    while channel_impl.start_typing_calls.load(Ordering::SeqCst) < 2 {
                        tokio::task::yield_now().await;
                    }
                })
                .await
                .expect("approved work should resume typing");
            } else {
                tokio::task::yield_now().await;
                assert_eq!(
                    channel_impl.start_typing_calls.load(Ordering::SeqCst),
                    1,
                    "denied or timed-out work must not resume typing"
                );
            }

            typing.pause().await;
        }
    }

