    struct SendViaTextRoutingProvider;

    fn send_via_text_tool_call() -> String {
        "<tool_call>\n{\"name\":\"send_via\",\"arguments\":{\"modality\":\"text\"}}\n</tool_call>"
            .to_string()
    }

    #[async_trait::async_trait]
    impl ModelProvider for SendViaTextRoutingProvider {
        async fn chat_with_system(
            &self,
            _system_prompt: Option<&str>,
            _message: &str,
            _model: &str,
            _temperature: Option<f64>,
        ) -> anyhow::Result<String> {
            Ok(send_via_text_tool_call())
        }

        async fn chat_with_history(
            &self,
            messages: &[ChatMessage],
            _model: &str,
            _temperature: Option<f64>,
        ) -> anyhow::Result<String> {
            if messages
                .iter()
                .any(|msg| msg.role == "user" && msg.content.contains("[Tool results]"))
            {
                Ok("the reply".to_string())
            } else {
                Ok(send_via_text_tool_call())
            }
        }
    }

    impl ::clawcrew_api::attribution::Attributable for SendViaTextRoutingProvider {
        fn role(&self) -> ::clawcrew_api::attribution::Role {
            ::clawcrew_api::attribution::Role::Provider(
                ::clawcrew_api::attribution::ProviderKind::Model(
                    ::clawcrew_api::attribution::ModelProviderKind::Custom,
                ),
            )
        }
        fn alias(&self) -> &str {
            "SendViaTextRoutingProvider"
        }
    }

